#pragma once
// Civil dates and time zones for the engine's recurring windows (core/windows.hpp).
//
// The zone data is compiled in (src/core/tzdata_table.cpp, generated by tools/tzdata_gen.py from
// one IANA tzdata release, tzdata_version()): a window gives the same UTC edges live, in a replay
// on another machine and in a backtest years later, whatever zoneinfo the host has. A zone keeps
// its offset on 2000-01-01, its transitions since, and the POSIX rule of its TZif file for every
// time after them. A POSIX TZ string ("EST5EDT,M3.2.0,M11.1.0") names a zone too.
//
// Seconds throughout. Lookups do not allocate or throw; TimeZone::find does, at configuration
// load.
#include "fastmm/core/fixed_point.hpp"

#include <cstdint>
#include <limits>
#include <optional>
#include <string>
#include <string_view>

namespace fastmm {

// Days since 1970-01-01 of a proleptic Gregorian date, and back (H. Hinnant's algorithms).
[[nodiscard]] constexpr std::int64_t civil_days(std::int64_t y, unsigned m, unsigned d) noexcept {
  y -= m <= 2 ? 1 : 0;
  const std::int64_t era = (y >= 0 ? y : y - 399) / 400;
  const auto yoe = static_cast<unsigned>(y - era * 400);
  const unsigned doy = (153 * (m > 2 ? m - 3 : m + 9) + 2) / 5 + d - 1;
  const unsigned doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
  return era * 146097 + static_cast<std::int64_t>(doe) - 719468;
}
struct CivilDate {
  std::int64_t y = 1970;
  unsigned m = 1;
  unsigned d = 1;
};
[[nodiscard]] constexpr CivilDate civil_date(std::int64_t z) noexcept {
  z += 719468;
  const std::int64_t era = (z >= 0 ? z : z - 146096) / 146097;
  const auto doe = static_cast<unsigned>(z - era * 146097);
  const unsigned yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
  const unsigned doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
  const unsigned mp = (5 * doy + 2) / 153;
  const unsigned d = doy - (153 * mp + 2) / 5 + 1;
  const unsigned m = mp < 10 ? mp + 3 : mp - 9;
  return {static_cast<std::int64_t>(yoe) + era * 400 + (m <= 2 ? 1 : 0), m, d};
}
// 0 Monday ... 6 Sunday.
[[nodiscard]] constexpr unsigned civil_weekday(std::int64_t z) noexcept {
  return static_cast<unsigned>(((z % 7) + 7 + 3) % 7);  // 1970-01-01 was a Thursday
}

// A POSIX TZ rule: a standard offset and, with daylight saving time, its offset and the two
// changes of each year. Offsets are seconds east of UTC.
struct TzRule {
  // A change's date: Jn (day 1..365, February 29 never counted), n (day 0..365) or Mm.w.d (day d,
  // 0 Sunday, of week w, 5 the last, of month m); and the local time of the change.
  struct Change {
    char kind = 'M';
    std::int16_t a = 0;
    std::int16_t b = 0;
    std::int16_t c = 0;
    std::int32_t time_s = 7200;
  };
  std::int32_t std_offset = 0;
  std::int32_t dst_offset = 0;
  bool has_dst = false;
  Change start;  // into daylight saving time, in local standard time
  Change end;    // out of it, in local daylight time

  [[nodiscard]] std::int32_t offset_at(std::int64_t utc_s) const noexcept;
  // The text read as a rule; an empty string, or the reason it is not one.
  [[nodiscard]] static std::string parse(std::string_view text, TzRule& out);
};

// One transition of an embedded zone: from `at` (UTC seconds) the offset is `offset`.
struct TzTransition {
  std::int64_t at;
  std::int32_t offset;
};

class TimeZone {
 public:
  static constexpr std::int64_t kNoRule = std::numeric_limits<std::int64_t>::max();

  TimeZone() = default;  // UTC
  // An IANA name of the tzdata this build carries, or a POSIX TZ rule. nullopt, and the reason in
  // `error`, for anything else.
  [[nodiscard]] static std::optional<TimeZone> find(std::string_view name, std::string* error);

  [[nodiscard]] const std::string& name() const noexcept { return name_; }
  // Seconds east of UTC at that instant.
  [[nodiscard]] std::int32_t offset_at(std::int64_t utc_s) const noexcept;
  // The first instant at which the local clock reads `local_s` (seconds since 1970-01-01 in local
  // time) or later. A time the clock skips (spring forward) gives the instant it jumps past it; a
  // time it shows twice (fall back) gives the first.
  [[nodiscard]] std::int64_t to_utc(std::int64_t local_s) const noexcept;

 private:
  std::string name_ = "UTC";
  const TzTransition* transitions_ = nullptr;
  std::uint32_t count_ = 0;
  std::int32_t offset0_ = 0;
  std::int64_t rule_from_ = kNoRule;
  TzRule rule_;
};

// The IANA tzdata release compiled in ("2026e").
[[nodiscard]] std::string_view tzdata_version() noexcept;

}  // namespace fastmm
